<?php if(in_array($document->status,['draft','returned'])): ?><?php if (app(\Illuminate\Contracts\Auth\Access\Gate::class)->check('planning.'.$document->type.'_create')): ?><a href="<?php echo e(route('planning.edit',$document)); ?>">Edit draft</a><?php endif; ?> <?php if (app(\Illuminate\Contracts\Auth\Access\Gate::class)->check('planning.'.$document->type.'_submit')): ?><form method="POST" action="<?php echo e(route('planning.action',$document)); ?>"><?php echo csrf_field(); ?><input type="hidden" name="version" value="<?php echo e($document->version); ?>"><button class="btn-primary" name="action" value="submit">Submit for approval</button></form><?php endif; ?> <?php endif; ?>
