<div class="kcard overflow-x-auto"><table class="w-full text-sm"><thead><tr><th>Item</th><th>Owner / due date</th><th><?php echo e($document->type==='budget'?'Allocation':'Target / budget'); ?></th><th>Definition of Done</th></tr></thead><tbody><?php $__currentLoopData = $document->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td class="max-w-md"><?php echo e($item->title); ?><div class="text-xs text-gray-500 whitespace-pre-line"><?php echo e($item->description); ?></div></td><td><?php echo e($item->owner?->name ?? $document->creator?->name); ?><div class="text-xs"><?php echo e($item->due_on); ?></div></td><td><?php if($document->type==='budget'): ?>Rs <?php echo e(number_format($item->amount,2)); ?><?php if(isset($publications[$item->id])): ?><div class="text-xs text-teal-700">Published to Department Budgets</div><?php endif; ?> <?php else: ?> <?php echo e($item->target); ?> <?php echo e($item->metric); ?> <?php if($item->requires_budget): ?><div class="text-xs">Budget required</div><?php endif; ?> <?php endif; ?></td><td class="max-w-sm whitespace-pre-line"><?php echo e($item->definition_of_done); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></div>
